```python
import json

def convert_to_json(response):
    return json.loads(response.body)

# Example usage:
response = {
    'status': 'database_exploded'
}

json_response = convert_to_json(response)
print(json_response)
```

Alternatively, you can use the `json.dumps` function to convert the response body to a JSON string:

```python
import json

def convert_to_json(response):
    return json.dumps(response)

# Example usage:
response = {
    'status': 'database_exploded'
}

json_response = convert_to_json(response)
print(json_response)
```

